Lemma bil_live_fst : forall lset (lps : list Z) (ps : list pixe) bxarr bxa pxarr pxa rng spat kfr kidx nc bil (vsc : pixv) pixsc (L : list (Z * Z)),
  length lps = length ps ->
  map fst (ls_live lset lps ps
             (rev (flat_map (fun e => [(pe_pix e, 64); (p_data (pe_v e), rsize (pe_v e))]) ps)
              ++ pixa_live pxa pxarr bxa bxarr 10 ((rng, 1024) :: (spat, 44) :: (kfr, 1024) :: (kidx, 1024) :: (nc, 40) :: (bil, 104)
                   :: (p_data vsc, 4 * (p_wpl vsc * p_h vsc)) :: (pixsc, 64) :: L)))
  = (rev lps ++ lset :: rev (flat_map pe_chunks ps) ++ [bxarr; bxa; pxarr; pxa; rng; spat; kfr; kidx; nc; bil; p_data vsc; pixsc]) ++ map fst L.
Proof.
