Lemma bil_nodup : forall (lps fm B : list Z) (lset bxarr bxa pxarr pxa rng spat kfr kidx nc bil dsc pixsc pix dv : Z),
  List.NoDup ((rev lps ++ lset :: rev fm ++ [bxarr; bxa; pxarr; pxa; rng; spat; kfr; kidx; nc; bil; dsc; pixsc]) ++ B) ->
  In pix B -> In dv B -> pix <> dv ->
  List.NoDup ([bil; pix; pixsc; dv; dsc; spat; rng; nc; kidx; kfr; pxa; pxarr; bxa; bxarr; lset] ++ fm ++ lps).
